import { reportApi } from '../../api/services';
import { Button } from '../../components/ui';
import { FileSpreadsheet, FileText, Download } from 'lucide-react';
import toast from 'react-hot-toast';

function downloadBlob(blob, filename) {
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  a.click();
  URL.revokeObjectURL(url);
}

export default function ReportsPage() {
  const handleExport = async (format) => {
    try {
      const { data } = await reportApi.exportEmployees(format);
      const ext = format === 'excel' ? 'xlsx' : format;
      downloadBlob(data, `employees_report.${ext}`);
      toast.success('Report downloaded');
    } catch {
      toast.error('Export failed');
    }
  };

  return (
    <div className="space-y-6 max-w-2xl">
      <div className="bg-white rounded-xl border border-slate-200 p-6">
        <h2 className="text-base font-semibold text-slate-800 mb-1">Employee Reports</h2>
        <p className="text-sm text-slate-500 mb-5">Export employee data in your preferred format.</p>
        <div className="flex flex-wrap gap-3">
          <Button onClick={() => handleExport('excel')}>
            <FileSpreadsheet size={16} /> Export Excel
          </Button>
          <Button variant="secondary" onClick={() => handleExport('csv')}>
            <Download size={16} /> Export CSV
          </Button>
          <Button variant="secondary" onClick={() => handleExport('pdf')}>
            <FileText size={16} /> Export PDF
          </Button>
        </div>
      </div>

      <div className="bg-white rounded-xl border border-slate-200 p-6">
        <h2 className="text-base font-semibold text-slate-800 mb-1">More Reports</h2>
        <p className="text-sm text-slate-500">Additional report types coming soon.</p>
        <ul className="mt-4 space-y-2 text-sm text-slate-600">
          {['Asset Utilization Report', 'Document Expiry Report', 'Headcount by Department', 'Joining & Attrition Trend'].map((r) => (
            <li key={r} className="flex items-center gap-2 text-slate-400">
              <span className="w-1.5 h-1.5 bg-slate-300 rounded-full" />
              {r} <span className="text-xs bg-slate-100 px-2 py-0.5 rounded-full">Coming soon</span>
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
}
